package com.example.input_ds.data

import android.content.Context

/**
 * 拼音 → 汉字候选词词典
 *
 * 优先从 assets/pinyin_map.txt 加载完整字库（4000+ 汉字），
 * 加载失败时回退到内置的兜底数据。
 */
object CharacterDictionary {

    /** 字符条目：汉字 + 使用频率权重 */
    data class CharEntry(val char: String, val weight: Int)

    /** 已加载的完整字库（null = 尚未初始化，用兜底数据） */
    private var assetMap: Map<String, List<CharEntry>>? = null

    /** 初始化：从 assets 加载完整字库 */
    fun init(context: Context) {
        if (assetMap != null) return
        try {
            assetMap = PinyinCharLoader.load(context)
        } catch (e: Exception) {
            e.printStackTrace()
        }
    }

    /** 当前使用的字库：优先 assets，回退兜底 */
    val PINYIN_TO_CHARS: Map<String, List<CharEntry>>
        get() = assetMap ?: FALLBACK_MAP

